/// Handle identity is scoped to one document ID and one live slot generation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct DocumentHandle {
    pub document_id: u64,
    pub slot: u32,
    pub generation: u32,
}

/// Byte range in the immutable borrowed source.
